/* V16.8 offline MCQ bank — starter set written from this app's guideline sections (EAU 2026, UICC TNM 9, ESE 2023).
   Each question: one correct option (answer = index), a short explanation and the app section it comes from.
   Options are shuffled when shown. AI-generated questions are added on the phone and stored separately. */
const MCQ_BANK = [
// ---------------- Urinary Tract Fistulae (Campbell 13e Ch. 121) ----------------
{id:'fi1',topic:'Urinary Tract Fistulae',level:'intern',section:'2. Aetiology & epidemiology',stem:'In high-income countries, what is the most common cause of vesicovaginal fistula?',options:['Benign hysterectomy','Prolonged obstructed labour','Pelvic radiotherapy','Cervical cancer invasion'],answer:0,explain:'In high-resource settings VVF is mostly iatrogenic, and benign hysterectomy is the commonest cause. Obstructed labour dominates in low-resource settings.'},
{id:'fi2',topic:'Urinary Tract Fistulae',level:'intern',section:'3. Presentation & evaluation',stem:'Continuous leakage per vaginam begins 10 days after abdominal hysterectomy. Methylene blue is instilled into the bladder; the vaginal swab is wet but NOT blue, and turns orange after oral phenazopyridine. Most likely diagnosis?',options:['Ureterovaginal fistula','Vesicovaginal fistula','Urethrovaginal fistula','Stress urinary incontinence'],answer:0,explain:'Orange staining from renal urine without blue dye from the bladder points to a ureterovaginal fistula. A blue swab would indicate a bladder or urethral fistula.'},
{id:'fi3',topic:'Urinary Tract Fistulae',level:'resident',section:'3. Presentation & evaluation',stem:'A post-hysterectomy VVF is confirmed on cystoscopy. Which further investigation is mandatory before planning repair?',options:['CT urography (or retrograde pyelography) to assess the ureters','MRI of the lumbar spine','Urodynamic study','Renal DMSA scan'],answer:0,explain:'About 10% of VVFs have a coexisting ureteric injury or ureterovaginal fistula. Upper-tract imaging changes the operation and must precede repair.'},
{id:'fi4',topic:'Urinary Tract Fistulae',level:'resident',section:'4. Timing & conservative management',stem:'A 4 mm VVF is recognised 5 days after hysterectomy; tissues are healthy and not irradiated. Best initial management?',options:['Continuous catheter drainage with weekly review','Immediate abdominal O\'Connor repair','Urinary diversion','Wait 6 months with pads, then repair'],answer:0,explain:'A small, fresh, non-irradiated fistula may close with continuous bladder drainage. Review weekly; if it still leaks after about 4–6 weeks, plan repair. Routine 6-month delay has no proven benefit.'},
{id:'fi5',topic:'Urinary Tract Fistulae',level:'exam',section:'1. Definitions, types & classification',stem:'Obstetric VVF whose distal edge lies 2 cm from the external urethral meatus, 2 cm in size, with moderate fibrosis. Goh classification?',options:['Type 3b ii','Type 2a i','Type 4c iii','Type 1b ii'],answer:0,explain:'Distal edge 1.5–<2.5 cm from the meatus = type 3; size 1.5–3 cm = b; moderate or severe fibrosis = ii.'},
{id:'fi6',topic:'Urinary Tract Fistulae',level:'resident',section:'6. Vaginal approaches',stem:'Small post-hysterectomy fistula at the vaginal vault, well away from the ureteric orifices. Which operation suits it best?',options:['Latzko partial colpocleisis (vaginal)','Ileal conduit urinary diversion','Augmentation cystoplasty','Bilateral nephrostomies'],answer:0,explain:'The Latzko technique closes a vault fistula vaginally without opening the bladder, with high success. Counsel about slight vaginal shortening.'},
{id:'fi7',topic:'Urinary Tract Fistulae',level:'exam',section:'10. Radiation, malignant & irreparable fistulae',stem:'VVF appears 2 years after pelvic radiotherapy for cervical cancer. Which is the most appropriate principle?',options:['Biopsy the edge, then delayed repair with vascularised tissue interposition','Catheter drainage alone, as it usually closes','Immediate primary repair without a flap','Fibrin glue injection as definitive treatment'],answer:0,explain:'Radiation fistulae rarely close spontaneously. Exclude recurrence with a biopsy, allow the injury to mature (about 6–12 months), and always interpose a vascularised flap (Martius, gracilis, rectus or omentum).'},
{id:'fi8',topic:'Urinary Tract Fistulae',level:'resident',section:'9. Uro-enteric fistulae',stem:'Most common cause of colovesical fistula?',options:['Diverticular disease','Colorectal carcinoma','Crohn\'s disease','Pelvic radiotherapy'],answer:0,explain:'Diverticulitis causes most colovesical fistulae, followed by colorectal cancer. Colonoscopy is essential to exclude malignancy.'},
{id:'fi9',topic:'Urinary Tract Fistulae',level:'resident',section:'8. Ureterovaginal, vesicouterine & urethrovaginal fistulae',stem:'After a caesarean section, a woman has cyclical haematuria, amenorrhoea and is fully continent. Most likely diagnosis?',options:['Vesicouterine fistula (Youssef syndrome)','Vesicovaginal fistula','Ureterovaginal fistula','Endometriosis of the ureter'],answer:0,explain:'In Youssef syndrome menstrual blood drains into the bladder (menouria); continence is preserved because the uterine isthmus acts as a sphincter.'},
{id:'fi10',topic:'Urinary Tract Fistulae',level:'intern',section:'11. Post-operative care, outcomes & prevention',stem:'After successful repair of an obstetric VVF, how should future deliveries be managed?',options:['Planned caesarean section','Vaginal delivery with an episiotomy','Home birth with a midwife','Assisted vaginal delivery with forceps'],answer:0,explain:'Planned caesarean delivery protects the repair. Counsel the woman and plan facility-based care for any future pregnancy.'},
// ---------------- Female Urinary Incontinence (V16.11) ----------------
{id:'fu1',topic:'Female Urinary Incontinence',level:'resident',section:'2. Evaluation',stem:'A healthy 45-year-old with pure SUI, a positive cough stress test, normal PVR and no prolapse or previous surgery wants a sling. Are urodynamics required first?',options:['No — they may be omitted in this index patient','Yes — always before any SUI surgery','Yes — to measure the abdominal leak point pressure','Only if the urinalysis is abnormal'],answer:0,explain:'AUA/SUFU: urodynamics may be omitted in the index patient with demonstrable SUI and normal emptying. The ValUE trial showed non-inferior outcomes without them.'},
{id:'fu2',topic:'Female Urinary Incontinence',level:'intern',section:'3. Conservative & non-surgical treatment',stem:'First-line treatment for stress urinary incontinence in women?',options:['Supervised pelvic floor muscle training for at least 3 months','Duloxetine','Vaginal laser therapy','Mid-urethral sling'],answer:0,explain:'Supervised PFMT for at least 3 months, with lifestyle measures such as weight loss, is first-line. Vaginal laser lacks sufficient evidence.'},
{id:'fu3',topic:'Female Urinary Incontinence',level:'exam',section:'5. Complicated & recurrent SUI, MUI',stem:'A woman needs a urethral diverticulectomy and also has bothersome SUI. Which concomitant anti-incontinence procedure is appropriate?',options:['Autologous fascial (pubovaginal) sling','Retropubic synthetic mid-urethral sling','Transobturator synthetic sling','Single-incision mini-sling'],answer:0,explain:'AUA: do not place a synthetic MUS at the same time as diverticulectomy, urethrovaginal fistula repair or urethral mesh excision. Use autologous fascia.'},
{id:'fu4',topic:'Female Urinary Incontinence',level:'resident',section:'4. Surgery for uncomplicated SUI',stem:'Compared with a transobturator tape, a retropubic mid-urethral sling has more of which complication?',options:['Bladder perforation and voiding dysfunction','Groin and thigh pain','Vaginal mesh exposure','De novo dyspareunia'],answer:0,explain:'Retropubic slings carry more bladder perforation (hence intraoperative cystoscopy) and voiding dysfunction; transobturator slings cause more groin and thigh pain.'},
{id:'fu5',topic:'Female Urinary Incontinence',level:'resident',section:'6. Complications of slings & mesh',stem:'Ten days after a retropubic sling, a woman is in retention with a PVR of 450 mL. Best management?',options:['Catheterise or start CISC, and loosen or incise the sling early if it persists','Wait 6 months before any intervention','Start an antimuscarinic','Remove the whole sling through an abdominal approach immediately'],answer:0,explain:'Early post-sling obstruction is drained, then managed by early loosening or incision (within about 2–6 weeks) if it does not settle.'},
{id:'fu6',topic:'Female Urinary Incontinence',level:'exam',section:'1. Definitions & types',stem:'Which feature makes an SUI patient "complicated" (non-index) under AUA/SUFU?',options:['Urgency-predominant mixed incontinence','Age over 50','Parity of three','BMI of 28'],answer:0,explain:'Non-index features include urgency-predominant MUI, prolapse grade 3–4, previous SUI surgery, neurogenic LUTD, incomplete emptying, radiation and inability to demonstrate SUI.'},
// ---------------- Overactive Bladder & Nocturia (V16.11) ----------------
{id:'oab1',topic:'Overactive Bladder & Nocturia',level:'intern',section:'3. Behavioural & first-line treatment',stem:'Which treatment should be offered to every patient with OAB (AUA/SUFU 2024)?',options:['Bladder training','Onabotulinumtoxin A','Sacral neuromodulation','Mirabegron'],answer:0,explain:'Bladder training is offered to all patients with OAB (strong recommendation, grade A).'},
{id:'oab2',topic:'Overactive Bladder & Nocturia',level:'resident',section:'4. Pharmacotherapy',stem:'A 78-year-old with mild cognitive impairment has bothersome OAB despite behavioural therapy. Most suitable drug?',options:['A β3 agonist such as mirabegron or vibegron','Oxybutynin immediate release','Tolterodine plus oxybutynin','Desmopressin'],answer:0,explain:'Antimuscarinics carry a cumulative, dose-related dementia risk that must be discussed. β3 agonists avoid anticholinergic burden and are preferred in cognitively vulnerable patients.'},
{id:'oab3',topic:'Overactive Bladder & Nocturia',level:'resident',section:'5. Third-line & refractory OAB',stem:'Before intradetrusor onabotulinumtoxinA 100 U for idiopathic OAB, the patient must be:',options:['Willing and able to perform clean intermittent self-catheterisation','Over 65 years old','On an antimuscarinic for at least 2 years','Free of urinary frequency'],answer:0,explain:'Raised PVR or retention needing CISC occurs in about 5–10%, so the patient must accept CISC.'},
{id:'oab4',topic:'Overactive Bladder & Nocturia',level:'exam',section:'1. Definitions',stem:'Frequency-volume chart: 24-h volume 2000 mL, nocturnal volume (including first morning void) 900 mL, age 70. Interpretation?',options:['Nocturnal polyuria (NPi 45%)','Global polyuria','Reduced bladder capacity only','Normal'],answer:0,explain:'NPi = 900/2000 = 45%, above the 33% cut-off for older adults: nocturnal polyuria.'},
{id:'oab5',topic:'Overactive Bladder & Nocturia',level:'resident',section:'6. Nocturia management',stem:'When starting low-dose desmopressin for nocturnal polyuria in an older patient, what monitoring is essential?',options:['Serum sodium at baseline, within the first week and at 1 month','Liver function tests every 3 months','PSA at 6 weeks','Fasting glucose weekly'],answer:0,explain:'Hyponatraemia risk rises with age, heart failure and renal impairment; sodium is checked at baseline, early (within a week) and at 1 month, and after dose changes.'},
{id:'oab6',topic:'Overactive Bladder & Nocturia',level:'intern',section:'2. Evaluation',stem:'A woman with urgency and frequency has microscopic haematuria. Before treating as OAB you should:',options:['Investigate the haematuria (cystoscopy, imaging, cytology as indicated)','Start mirabegron and review in 3 months','Perform urodynamics','Advise more fluids'],answer:0,explain:'OAB is a diagnosis of exclusion. Urgency with haematuria may be carcinoma in situ, stone or infection and must be investigated.'},
// ---------------- Urodynamics (V16.11) ----------------
{id:'uds1',topic:'Urodynamics',level:'resident',section:'4. Pressure-flow study & indices',stem:'A man has PdetQmax 70 cmH2O and Qmax 8 mL/s. BOOI and class?',options:['54 — obstructed','30 — equivocal','14 — unobstructed','110 — strong contractility'],answer:0,explain:'BOOI = PdetQmax − 2Qmax = 70 − 16 = 54, above 40: obstructed. (BCI = 70 + 40 = 110, normal contractility.)'},
{id:'uds2',topic:'Urodynamics',level:'resident',section:'4. Pressure-flow study & indices',stem:'A man has PdetQmax 30 cmH2O and Qmax 6 mL/s. What does the BCI show?',options:['BCI 60 — weak contractility (detrusor underactivity)','BCI 60 — normal','BCI 18 — obstructed','BCI 150 — strong'],answer:0,explain:'BCI = PdetQmax + 5Qmax = 30 + 30 = 60, below 100: weak. BOOI = 18, unobstructed — a low flow from underactivity, not obstruction.'},
{id:'uds3',topic:'Urodynamics',level:'intern',section:'3. Filling cystometry',stem:'During filling cystometry, the patient coughs: Pves and Pabd rise equally and Pdet barely changes. This shows:',options:['Good pressure transmission (quality check passed)','Detrusor overactivity','Low compliance','Catheter displacement'],answer:0,explain:'Equal cough spikes in Pves and Pabd with minimal Pdet change confirm good pressure transmission; repeat during filling and before voiding.'},
{id:'uds4',topic:'Urodynamics',level:'exam',section:'3. Filling cystometry',stem:'In a neurogenic bladder, which storage finding signals the highest risk to the upper tracts?',options:['Detrusor pressure persistently above 40 cmH2O during filling','First desire at 150 mL','Abdominal leak point pressure of 95 cmH2O','Maximum capacity of 500 mL'],answer:0,explain:'A filling or detrusor leak point pressure above 40 cmH2O (McGuire) is associated with upper-tract deterioration.'},
{id:'uds5',topic:'Urodynamics',level:'resident',section:'2. Uroflowmetry & PVR',stem:'A free uroflow with a voided volume of 90 mL shows Qmax 9 mL/s. Next step?',options:['Repeat the flow with a voided volume of at least 150 mL','Diagnose bladder outlet obstruction','Proceed to surgery','Diagnose detrusor underactivity'],answer:0,explain:'Flows below 150 mL voided volume are unreliable; and even a valid low Qmax cannot separate obstruction from underactivity without pressure-flow studies.'},
{id:'uds6',topic:'Urodynamics',level:'exam',section:'4. Pressure-flow study & indices',stem:'Which statement about diagnosing female bladder outlet obstruction is correct?',options:['No universally accepted index exists; criteria such as Defreitas or BOOIf are combined with clinical and video findings','The male BOOI (cut-off 40) applies unchanged','Free flow Qmax alone is diagnostic','A BCI below 100 proves obstruction'],answer:0,explain:'Women void at lower pressures; the male ICS nomogram should not be applied. Use female criteria (e.g. Qmax ≤ 12 with PdetQmax ≥ 25; BOOIf = PdetQmax − 2.2Qmax) with videourodynamics.'},
// ---------------- Pelvic Organ Prolapse (V16.11) ----------------
{id:'pop1',topic:'Pelvic Organ Prolapse',level:'resident',section:'2. POP-Q staging',stem:'POP-Q: Ba +2, C −6, Bp −2, tvl 9. Stage?',options:['Stage III','Stage II','Stage IV','Stage I'],answer:0,explain:'Leading point Ba +2: more than 1 cm beyond the hymen but less than tvl − 2 (7), so stage III (anterior compartment).'},
{id:'pop2',topic:'Pelvic Organ Prolapse',level:'intern',section:'2. POP-Q staging',stem:'In POP-Q, points Aa and Ap are defined as:',options:['Fixed points 3 cm proximal to the hymen, ranging from −3 to +3','The most dependent parts of the anterior and posterior walls','The cervix and posterior fornix','The genital hiatus and perineal body'],answer:0,explain:'Aa and Ap are fixed 3 cm inside the hymen. Ba and Bp are the most dependent points of each wall.'},
{id:'pop3',topic:'Pelvic Organ Prolapse',level:'resident',section:'5. Surgery',stem:'The most durable repair for recurrent post-hysterectomy vault prolapse in an active 55-year-old?',options:['Sacrocolpopexy with lightweight mesh','Anterior colporrhaphy alone','Colpocleisis','Transvaginal polypropylene mesh kit'],answer:0,explain:'Abdominal (laparoscopic or robotic) sacrocolpopexy is the most durable apical repair. Colpocleisis ends intercourse; transvaginal mesh for POP is withdrawn or restricted.'},
{id:'pop4',topic:'Pelvic Organ Prolapse',level:'exam',section:'3. Evaluation',stem:'Before prolapse surgery, why reduce the prolapse and repeat the cough stress test?',options:['To unmask occult SUI that may appear after repair','To measure total vaginal length','To grade the rectocele','To rule out detrusor overactivity'],answer:0,explain:'A kinked urethra can hide SUI. Occult SUI guides counselling about a concomitant or staged sling.'},
{id:'pop5',topic:'Pelvic Organ Prolapse',level:'intern',section:'4. Conservative treatment',stem:'A frail 86-year-old with symptomatic stage III uterine prolapse wants to avoid surgery. Best option?',options:['Vaginal pessary with vaginal oestrogen and regular review','Sacrocolpopexy','Observation only, never review','Pelvic floor training alone for stage IV'],answer:0,explain:'A pessary suits the frail or those avoiding surgery; vaginal oestrogen and regular changes reduce erosion. Colpocleisis is a surgical alternative if she no longer wants intercourse.'},
// ---------------- Bladder Pain Syndrome / Interstitial Cystitis (V16.11) ----------------
{id:'bps1',topic:'Bladder Pain Syndrome / Interstitial Cystitis',level:'resident',section:'1. Definition & phenotypes',stem:'Why is cystoscopy valuable in suspected IC/BPS?',options:['To identify Hunner lesions, which respond to lesion-directed treatment','Glomerulations after hydrodistension are diagnostic','It is mandatory for diagnosis in every patient','To measure bladder compliance'],answer:0,explain:'Hunner lesions are a distinct phenotype treated by fulguration, laser or triamcinolone injection. Glomerulations are non-specific.'},
{id:'bps2',topic:'Bladder Pain Syndrome / Interstitial Cystitis',level:'exam',section:'4. Oral, intravesical & procedural therapy',stem:'A patient on long-term pentosan polysulfate for IC/BPS needs which monitoring?',options:['Baseline and periodic retinal examination for maculopathy','Monthly full blood count','Annual bone density scan','Serum magnesium'],answer:0,explain:'PPS is associated with a pigmentary maculopathy; discuss the risk and arrange eye examinations.'},
{id:'bps3',topic:'Bladder Pain Syndrome / Interstitial Cystitis',level:'resident',section:'3. Treatment principles',stem:'Pelvic floor tenderness in IC/BPS is best treated with:',options:['Manual myofascial physical therapy','Kegel strengthening exercises','Long-term oral antibiotics','Intravesical BCG'],answer:0,explain:'Myofascial release helps; strengthening exercises can worsen pain. Long-term antibiotics and intravesical BCG should not be used (AUA).'},
{id:'bps4',topic:'Bladder Pain Syndrome / Interstitial Cystitis',level:'intern',section:'2. Evaluation',stem:'A 60-year-old smoker with suspected IC/BPS has microscopic haematuria. Essential step?',options:['Cystoscopy and urine cytology to exclude carcinoma in situ','Start amitriptyline','Intravesical DMSO','Dietary changes only'],answer:0,explain:'CIS and bladder cancer can mimic IC/BPS; haematuria and smoking demand cystoscopy and cytology.'},
// ---------------- Female Voiding Dysfunction & Urethral Diverticulum (V16.11) ----------------
{id:'fvd1',topic:'Female Voiding Dysfunction & Urethral Diverticulum',level:'resident',section:'3. Urethral diverticulum: features & imaging',stem:'Best imaging test to characterise a female urethral diverticulum?',options:['Pelvic MRI (T2-weighted)','Plain abdominal X-ray','Intravenous urography','Renal ultrasound'],answer:0,explain:'MRI shows size, configuration (e.g. saddlebag), communication and any solid component, and is the most accurate test.'},
{id:'fvd2',topic:'Female Voiding Dysfunction & Urethral Diverticulum',level:'exam',section:'1. Female voiding dysfunction: causes',stem:'A 28-year-old woman has painless retention of 1.2 L without urgency; catheter removal is painful. Sphincter EMG shows complex repetitive discharges. Diagnosis and best-evidence treatment?',options:['Fowler\'s syndrome — sacral neuromodulation','Detrusor underactivity — bethanechol','Primary bladder neck obstruction — bladder neck incision','Urethral stricture — urethrotomy'],answer:0,explain:'Fowler\'s syndrome is failure of the striated sphincter to relax; SNM is the treatment with the best evidence.'},
{id:'fvd3',topic:'Female Voiding Dysfunction & Urethral Diverticulum',level:'intern',section:'3. Urethral diverticulum: features & imaging',stem:'The classic "3 Ds" of female urethral diverticulum are:',options:['Dysuria, dyspareunia and post-void dribbling','Diarrhoea, dysuria and dizziness','Dribbling, diplopia and dysphagia','Dyspareunia, dysmenorrhoea and dyschezia'],answer:0,explain:'Dysuria, dyspareunia and post-void dribbling, often with recurrent UTI and a tender anterior vaginal mass.'},
{id:'fvd4',topic:'Female Voiding Dysfunction & Urethral Diverticulum',level:'resident',section:'4. Urethral diverticulum: treatment',stem:'A key principle of transvaginal urethral diverticulectomy is:',options:['Complete sac excision with watertight, non-overlapping layered closure','Leaving the sac neck open to drain','Single-layer closure under tension','Routine synthetic sling placement at the same time'],answer:0,explain:'Excise to the neck, close the urethra watertight, then periurethral fascia and vaginal flap in non-overlapping layers; Martius flap if tissue is poor. No synthetic sling.'},
{id:'fvd5',topic:'Female Voiding Dysfunction & Urethral Diverticulum',level:'resident',section:'2. Evaluation & management',stem:'Safest long-term bladder drainage for a woman with chronic retention from detrusor underactivity?',options:['Clean intermittent self-catheterisation','Long-term indwelling urethral catheter','Bethanechol alone','Bladder neck incision'],answer:0,explain:'CISC protects the bladder and upper tracts with fewer complications than indwelling catheters; drugs have little proven benefit.'},
// ---------------- Drug formulary (V16.13) ----------------
{id:'dbph1',topic:'Drugs: BPH & Male LUTS',level:'resident',section:'1. Alpha-1 blockers',stem:'A 66-year-old on tamsulosin for LUTS is listed for cataract surgery next month. What is the key counselling point?',options:['Tell the eye surgeon: there is a risk of intraoperative floppy iris syndrome','Stop tamsulosin 2 days before and the risk disappears','Switch to doxazosin, which carries no such risk','No action: alpha-blockers do not affect eye surgery'],answer:0,explain:'IFIS is most associated with tamsulosin but can occur with any α1-blocker and persists after stopping; the ophthalmologist must know in advance.'},
{id:'dbph2',topic:'Drugs: BPH & Male LUTS',level:'resident',section:'1. Alpha-1 blockers',stem:'Which alpha-blocker is contraindicated when creatinine clearance is below 30 mL/min?',options:['Silodosin','Tamsulosin','Alfuzosin','Doxazosin'],answer:0,explain:'Silodosin needs 4 mg at CrCl 30–50 and is contraindicated below 30 mL/min.'},
{id:'dbph3',topic:'Drugs: BPH & Male LUTS',level:'intern',section:'2. 5-alpha reductase inhibitors (5-ARIs)',stem:'A man has been on dutasteride for a year; his PSA is 2.1 ng/mL. For prostate cancer screening, this is best interpreted as roughly:',options:['4.2 ng/mL','2.1 ng/mL','1.05 ng/mL','Uninterpretable on a 5-ARI'],answer:0,explain:'5-ARIs halve PSA after 6–12 months, so double the on-treatment value; a rise from the nadir also needs evaluation.'},
{id:'dbph4',topic:'Drugs: BPH & Male LUTS',level:'exam',section:'2. 5-alpha reductase inhibitors (5-ARIs)',stem:'Which outcome is reduced by 5-ARIs but NOT by alpha-blocker monotherapy over the long term?',options:['Acute urinary retention and need for BPH surgery','Time to symptom improvement','Postural hypotension','Ejaculatory dysfunction'],answer:0,explain:'5-ARIs shrink the prostate and reduce retention and surgery (MTOPS, CombAT); α-blockers relieve symptoms quickly but do not alter progression.'},
{id:'dbph5',topic:'Drugs: BPH & Male LUTS',level:'resident',section:'3. PDE5 inhibitor for LUTS',stem:'Daily tadalafil 5 mg for LUTS/BPH is absolutely contraindicated with:',options:['Isosorbide mononitrate','Tamsulosin','Finasteride','Mirabegron'],answer:0,explain:'Any nitrate (or riociguat) with a PDE5 inhibitor risks severe hypotension. α-blocker combinations need caution, not prohibition.'},
{id:'doab1',topic:'Drugs: OAB, Bladder & Nocturia',level:'resident',section:'1. Antimuscarinics',stem:'Which antimuscarinic is a quaternary amine with the least blood–brain barrier penetration?',options:['Trospium','Oxybutynin','Tolterodine','Solifenacin'],answer:0,explain:'Trospium is a quaternary amine, renally excreted, with minimal CNS penetration — useful when cognition is a concern.'},
{id:'doab2',topic:'Drugs: OAB, Bladder & Nocturia',level:'resident',section:'2. Beta-3 agonists',stem:'Before starting mirabegron, which baseline check matters most?',options:['Blood pressure','Intraocular pressure','Serum sodium','ECG for QT in every patient'],answer:0,explain:'Mirabegron can raise blood pressure and is avoided in severe uncontrolled hypertension (≥ 180/110 mmHg).'},
{id:'doab3',topic:'Drugs: OAB, Bladder & Nocturia',level:'exam',section:'2. Beta-3 agonists',stem:'A patient on mirabegron also takes metoprolol and digoxin. Which interaction mechanism is relevant?',options:['Mirabegron moderately inhibits CYP2D6, and digoxin levels need monitoring','Mirabegron induces CYP3A4, lowering both drugs','Mirabegron is a strong P-gp inducer','There are no relevant interactions'],answer:0,explain:'Mirabegron inhibits CYP2D6 (raising metoprolol exposure) and increases digoxin levels; vibegron lacks the CYP2D6 effect.'},
{id:'doab4',topic:'Drugs: OAB, Bladder & Nocturia',level:'resident',section:'4. Desmopressin & nocturia drugs',stem:'Which is a contraindication to low-dose desmopressin for nocturnal polyuria?',options:['Heart failure treated with a loop diuretic','Age 55 years','Benign prostatic enlargement','Previous TURP'],answer:0,explain:'Heart failure, loop diuretics, hyponatraemia, polydipsia, SIADH and eGFR < 50 are contraindications; sodium must be monitored.'},
{id:'doab5',topic:'Drugs: OAB, Bladder & Nocturia',level:'intern',section:'3. Intradetrusor botulinum toxin',stem:'The usual onabotulinumtoxinA dose for idiopathic OAB is:',options:['100 U','200 U','300 U','50 U'],answer:0,explain:'100 U for idiopathic OAB; 200 U for neurogenic detrusor overactivity. Patients must be able to self-catheterise if retention occurs.'},
{id:'dsex1',topic:'Drugs: Sexual Medicine & Androgens',level:'resident',section:'1. PDE5 inhibitors',stem:'A man took tadalafil 20 mg last night and now has chest pain. How long should nitrates be avoided after the tadalafil dose?',options:['At least 48 hours','At least 6 hours','At least 12 hours','No restriction'],answer:0,explain:'Wait at least 48 hours after tadalafil (24 hours after sildenafil or vardenafil) before giving a nitrate; use other anti-anginal treatment meanwhile.'},
{id:'dsex2',topic:'Drugs: Sexual Medicine & Androgens',level:'resident',section:'2. Second-line ED drugs & priapism reversal',stem:'Ischaemic priapism of 6 hours persists after aspiration. Next drug step?',options:['Intracavernosal phenylephrine 100–500 µg/mL, 1 mL every 3–5 minutes with BP monitoring','Oral terbutaline and observe for 24 hours','Intracavernosal alprostadil','IV heparin infusion'],answer:0,explain:'Diluted intracavernosal phenylephrine with cardiovascular monitoring follows aspiration; shunting if it fails.'},
{id:'dsex3',topic:'Drugs: Sexual Medicine & Androgens',level:'exam',section:'4. Testosterone therapy & fertility-sparing alternatives',stem:'A 32-year-old with secondary hypogonadism wants to father a child. Best treatment?',options:['Clomiphene citrate or hCG to raise endogenous testosterone','Testosterone undecanoate injections','Testosterone gel 50 mg daily','Finasteride'],answer:0,explain:'Exogenous testosterone suppresses spermatogenesis; clomiphene or hCG preserve it in secondary hypogonadism.'},
{id:'dsex4',topic:'Drugs: Sexual Medicine & Androgens',level:'resident',section:'4. Testosterone therapy & fertility-sparing alternatives',stem:'On testosterone therapy, when should the dose be reduced or treatment withheld?',options:['Haematocrit above 54%','PSA rise of 0.1 ng/mL','Testosterone in the mid-normal range','Weight gain of 1 kg'],answer:0,explain:'Erythrocytosis is the commonest dose-limiting effect; reduce or stop if haematocrit exceeds 54%.'},
{id:'dsex5',topic:'Drugs: Sexual Medicine & Androgens',level:'resident',section:'3. Premature ejaculation',stem:'Before prescribing dapoxetine, which check is specifically recommended?',options:['Orthostatic blood pressure (syncope risk)','Serum prolactin','Penile Doppler','Semen analysis'],answer:0,explain:'Dapoxetine can cause syncope; check for orthostatic hypotension and avoid alcohol and other serotonergic drugs.'},
{id:'dsto1',topic:'Drugs: Stones (MET, Colic & Prevention)',level:'intern',section:'1. Renal colic & medical expulsive therapy',stem:'First-line analgesia for renal colic with normal renal function:',options:['An NSAID such as diclofenac','Pethidine','Hyoscine butylbromide alone','Oral codeine alone'],answer:0,explain:'NSAIDs are first-line and reduce re-presentation; opioids are second-line, and pethidine should be avoided.'},
{id:'dsto2',topic:'Drugs: Stones (MET, Colic & Prevention)',level:'resident',section:'1. Renal colic & medical expulsive therapy',stem:'Medical expulsive therapy with an alpha-blocker is most supported for:',options:['A distal ureteric stone larger than 5 mm without infection','An infected obstructed kidney','A 15 mm proximal ureteric stone','Any stone in pregnancy'],answer:0,explain:'EAU supports α-blockers for distal stones > 5 mm; infection or obstruction with sepsis needs drainage.'},
{id:'dsto3',topic:'Drugs: Stones (MET, Colic & Prevention)',level:'exam',section:'3. Calcium & uric acid stone prevention',stem:'What did the NOSTONE trial show about hydrochlorothiazide in recurrent calcium stone formers?',options:['No reduction in recurrence at 12.5–50 mg daily','A 50% reduction at 25 mg daily','Benefit only at 50 mg daily','Reduced recurrence but more stones in women'],answer:0,explain:'NOSTONE (NEJM 2023) found no dose of HCTZ reduced recurrence, with more hypokalaemia, gout and diabetes.'},
{id:'dsto4',topic:'Drugs: Stones (MET, Colic & Prevention)',level:'resident',section:'2. Urinary alkalinisation & citrate',stem:'Target urine pH for oral dissolution of uric acid stones:',options:['About 7.0–7.2','About 5.0–5.5','About 6.0','Above 8.0'],answer:0,explain:'Dissolution needs pH about 7.0–7.2 (prevention 6.5–7.0); cystine needs pH above 7.5.'},
{id:'dsto5',topic:'Drugs: Stones (MET, Colic & Prevention)',level:'exam',section:'3. Calcium & uric acid stone prevention',stem:'Which combination with allopurinol is dangerous?',options:['Azathioprine','Potassium citrate','Tamsulosin','Paracetamol'],answer:0,explain:'Allopurinol (and febuxostat) block xanthine oxidase, which metabolises azathioprine and mercaptopurine — causing severe marrow toxicity.'},
{id:'duti1',topic:'Drugs: Urinary Infections',level:'intern',section:'1. Uncomplicated cystitis',stem:'Nitrofurantoin should not be used for:',options:['Acute pyelonephritis','Uncomplicated cystitis in a non-pregnant woman','Low-dose prophylaxis of recurrent cystitis','Cystitis with normal renal function'],answer:0,explain:'Nitrofurantoin does not reach adequate tissue levels; it is for the bladder only. Also avoid if eGFR < 30.'},
{id:'duti2',topic:'Drugs: Urinary Infections',level:'resident',section:'1. Uncomplicated cystitis',stem:'Gepotidacin is approved for uncomplicated UTI in females. What is its regimen?',options:['1500 mg orally twice daily for 5 days','3 g single dose','100 mg twice daily for 5 days','400 mg three times daily for 3 days'],answer:0,explain:'Gepotidacin 1500 mg twice daily for 5 days; non-inferior to nitrofurantoin in EAGLE-2/3. The other regimens are fosfomycin, nitrofurantoin and pivmecillinam.'},
{id:'duti3',topic:'Drugs: Urinary Infections',level:'resident',section:'2. Pyelonephritis & complicated UTI',stem:'Which is a recognised fluoroquinolone safety concern that limits their use?',options:['Aortic aneurysm or dissection','Hyperkalaemia','Hypertrichosis','Gingival hyperplasia'],answer:0,explain:'FQ warnings include tendon rupture, aortic aneurysm/dissection, QT prolongation, dysglycaemia, neuropathy and CNS effects.'},
{id:'duti4',topic:'Drugs: Urinary Infections',level:'exam',section:'3. Recurrent UTI prevention & prophylaxis',stem:'In the ALTAR trial, methenamine hippurate for recurrent UTI prevention in women was:',options:['Non-inferior to daily low-dose antibiotic prophylaxis','Inferior to placebo','Superior to vaginal oestrogen','Effective only with urinary alkalinisation'],answer:0,explain:'Methenamine works in acidic urine; it must not be combined with alkalinisers. ALTAR showed non-inferiority to antibiotics.'},
{id:'duti5',topic:'Drugs: Urinary Infections',level:'resident',section:'4. Fungal UTI & other infections',stem:'Symptomatic Candida albicans cystitis in a woman with normal renal function. Treatment?',options:['Fluconazole 200 mg daily for 2 weeks','Caspofungin IV','Nitrofurantoin','No treatment ever needed'],answer:0,explain:'Fluconazole reaches high urine levels; echinocandins do not. Asymptomatic candiduria usually needs no treatment.'},
{id:'divh1',topic:'Drugs: Intravesical, Hormonal & Peri-operative',level:'resident',section:'1. Intravesical therapy for NMIBC',stem:'Which is a contraindication to giving intravesical BCG today?',options:['Visible haematuria after a traumatic catheterisation','Previous BCG induction','Age over 70','Intermediate-risk NMIBC'],answer:0,explain:'Traumatic catheterisation, visible haematuria, symptomatic UTI and the first 2 weeks after TURBT risk systemic BCG absorption.'},
{id:'divh2',topic:'Drugs: Intravesical, Hormonal & Peri-operative',level:'exam',section:'1. Intravesical therapy for NMIBC',stem:'Disseminated BCG infection is treated with antituberculous drugs. Which drug is ineffective against BCG?',options:['Pyrazinamide','Isoniazid','Rifampicin','Ethambutol'],answer:0,explain:'M. bovis BCG is intrinsically resistant to pyrazinamide; use isoniazid, rifampicin and ethambutol ± steroids.'},
{id:'divh3',topic:'Drugs: Intravesical, Hormonal & Peri-operative',level:'resident',section:'2. Androgen deprivation: practical pharmacology',stem:'A man with painful spinal metastases is starting an LHRH agonist. How do you prevent flare?',options:['Start an antiandrogen (e.g. bicalutamide) about a week before and continue for 2–4 weeks','Give the first injection at double dose','Start denosumab 120 mg the same day','No action is needed'],answer:0,explain:'Antiandrogen cover blocks the testosterone surge; an LHRH antagonist avoids flare altogether.'},
{id:'divh4',topic:'Drugs: Intravesical, Hormonal & Peri-operative',level:'resident',section:'3. Bladder, bleeding & peri-operative drugs',stem:'Phenazopyridine should be avoided in which patient?',options:['G6PD deficiency','Hypertension','BPH','Previous kidney stone'],answer:0,explain:'It can cause haemolysis and methaemoglobinaemia, especially with G6PD deficiency or renal impairment; it only relieves symptoms.'},
{id:'divh5',topic:'Drugs: Intravesical, Hormonal & Peri-operative',level:'exam',section:'2. Androgen deprivation: practical pharmacology',stem:'A man on ADT is switching off denosumab 60 mg. What is the main risk if it is stopped without a plan?',options:['Rebound bone loss and multiple vertebral fractures','Hypercalcaemic crisis within 24 hours','Testosterone flare','Osteonecrosis of the jaw immediately'],answer:0,explain:'Stopping denosumab causes rebound bone turnover; follow on with a bisphosphonate.'},
// ---------------- Ca Prostate ----------------
{id:'pca1',topic:'Ca Prostate',level:'resident',section:'3. TNM staging & risk',stem:'PSA 14 ng/mL, ISUP Grade Group 2 on biopsy, cT2a, no nodes. EAU 2026 risk group?',options:['Unfavourable intermediate risk','Favourable intermediate risk','Low risk','High risk'],answer:0,explain:'GG2 with PSA 10–20 is unfavourable intermediate. Favourable intermediate is GG1 with PSA 10–20, or GG2 with PSA <10.'},
{id:'pca2',topic:'Ca Prostate',level:'intern',section:'1. Diagnostic pathway',stem:'Preferred route for prostate biopsy according to EAU?',options:['Transperineal, because of the lower infection risk','Transrectal with a single dose of ciprofloxacin','Transurethral resection biopsy','Whichever route is quicker in OPD'],answer:0,explain:'EAU recommends transperineal biopsy, mainly because the risk of infection is lower than with the transrectal route.'},
{id:'pca3',topic:'Ca Prostate',level:'intern',section:'2. Histology • ISUP • pathology',stem:'Gleason score 4 + 3 = 7 corresponds to which ISUP Grade Group?',options:['Grade Group 3','Grade Group 2','Grade Group 4','Grade Group 1'],answer:0,explain:'3+3 = GG1, 3+4 = GG2, 4+3 = GG3, 8 = GG4, 9–10 = GG5.'},
{id:'pca4',topic:'Ca Prostate',level:'resident',section:'4. Localized / locally advanced treatment',stem:'62-year-old, PSA 6, GG1 in 2 of 12 cores, cT1c, MRI concordant. Recommended management?',options:['Active surveillance','Radical prostatectomy','Radiotherapy with 6 months of ADT','ADT alone'],answer:0,explain:'Low-risk disease: offer active surveillance with scheduled PSA, MRI and repeat biopsy. ADT has no role in low-risk disease.'},
{id:'pca5',topic:'Ca Prostate',level:'resident',section:'6. mHSPC • doublet • triplet • emerging biomarker-driven therapy',stem:'Fit man with newly diagnosed high-volume metastatic hormone-sensitive prostate cancer. Which option is NOT recommended?',options:['ADT alone','ADT + abiraterone','ADT + enzalutamide or apalutamide','ADT + docetaxel + darolutamide or abiraterone'],answer:0,explain:'ADT monotherapy is undertreatment for a fit mHSPC patient. Add an ARPI (doublet), or docetaxel plus an ARPI (triplet) for selected fit patients.'},
{id:'pca6',topic:'Ca Prostate',level:'exam',section:'5. Biochemical recurrence / salvage',stem:'PSA rises to 0.3 ng/mL two years after radical prostatectomy. Best imaging if it would change management?',options:['PSMA PET-CT','Bone scan and CT abdomen','mpMRI pelvis alone','No imaging until PSA >10'],answer:0,explain:'PSMA PET detects recurrence at low PSA levels and guides salvage therapy. Bone scan and CT have poor yield at a PSA below 10.'},
// ---------------- Ca Bladder ----------------
{id:'bca1',topic:'Ca Bladder',level:'intern',section:'3. NMIBC risk & treatment',stem:'Single 1.5 cm papillary tumour, low-grade on frozen section, completely resected. What should follow TURBT?',options:['A single immediate post-operative chemotherapy instillation','Induction BCG starting the next day','Radical cystectomy','No further treatment or follow-up'],answer:0,explain:'A single immediate instillation (for example mitomycin C or gemcitabine), ideally within 2 hours, reduces recurrence in presumed low-risk tumours. Never give BCG straight after resection.'},
{id:'bca2',topic:'Ca Bladder',level:'resident',section:'3. NMIBC risk & treatment',stem:'Which finding is an indication for re-TURBT within 2–6 weeks?',options:['pT1 high-grade tumour','Single Ta low-grade tumour with muscle in the specimen','Primary CIS alone treated with BCG','Recurrent Ta low-grade tumour under 1 cm'],answer:0,explain:'Re-resect T1 tumours, incomplete resections and specimens with no detrusor muscle (except Ta low-grade and primary CIS).'},
{id:'bca3',topic:'Ca Bladder',level:'resident',section:'10. BCG definitions / maintenance protocols',stem:'High-risk NMIBC on BCG. Recommended duration of maintenance?',options:['Full-dose BCG for 1–3 years after induction','Induction only (6 weekly instillations)','Maintenance for 6 months','Lifelong monthly instillations'],answer:0,explain:'High risk: induction plus maintenance for 1–3 years (3 years where available). Intermediate risk: 1 year.'},
{id:'bca4',topic:'Ca Bladder',level:'exam',section:'11. MIBC — every cisplatin branch',stem:'Which of these alone does NOT make a patient cisplatin-ineligible?',options:['Age over 75','ECOG performance status 2','Creatinine clearance below 60 mL/min','Grade 2 or worse hearing loss'],answer:0,explain:'Cisplatin-unfit (Galsky) criteria: ECOG ≥2, CrCl <60, hearing loss or neuropathy grade ≥2, NYHA III or worse. Age alone is not a criterion.'},
{id:'bca5',topic:'Ca Bladder',level:'resident',section:'6. Metastatic urothelial carcinoma',stem:'Preferred first-line treatment for fit patients with metastatic urothelial carcinoma, based on EV-302?',options:['Enfortumab vedotin + pembrolizumab','Gemcitabine + carboplatin alone','Pembrolizumab alone','Best supportive care'],answer:0,explain:'EV-302 showed better overall survival with EV + pembrolizumab than with platinum chemotherapy, so it is now the preferred first-line option.'},
{id:'bca6',topic:'Ca Bladder',level:'exam',section:'9. 2026 NMIBC classification / complete treatment branches',stem:'T1 high-grade NMIBC with micropapillary variant histology. EAU risk group and management?',options:['Very high risk: offer radical cystectomy','Intermediate risk: 1 year of chemotherapy instillations','Low risk: single instillation and surveillance','High risk: BCG only, cystectomy never discussed'],answer:0,explain:'Variant histology (micropapillary, plasmacytoid and others) or LVI places the tumour in the very-high-risk group. Offer immediate radical cystectomy.'},
// ---------------- UTUC ----------------
{id:'ut1',topic:'UTUC',level:'intern',section:'1. Diagnosis & staging',stem:'Best imaging test to diagnose and stage suspected upper tract urothelial carcinoma?',options:['CT urography','Ultrasound KUB','Intravenous urography','Plain X-ray KUB'],answer:0,explain:'CT urography has the highest diagnostic accuracy. Use ureteroscopy with biopsy and cytology to grade the tumour.'},
{id:'ut2',topic:'UTUC',level:'resident',section:'6. 2026 risk stratification / decision matrix',stem:'Which UTUC suits kidney-sparing endoscopic management?',options:['Unifocal, <2 cm, low-grade on biopsy, no invasion on CT','Multifocal tumour with hydronephrosis','High-grade cytology with a 3 cm mass','Tumour with local invasion on CT'],answer:0,explain:'Low-risk UTUC is unifocal, under 2 cm, low-grade on cytology and biopsy, with no invasive features on CT. Offer kidney-sparing treatment.'},
{id:'ut3',topic:'UTUC',level:'resident',section:'3. Local treatment',stem:'After radical nephroureterectomy, which measure reduces bladder recurrence?',options:['A single post-operative intravesical chemotherapy instillation','Six weekly BCG instillations','Lifelong antibiotic prophylaxis','Leaving the ureteric stump in place'],answer:0,explain:'A single post-operative instillation of chemotherapy (ODMIRT trial) lowers intravesical recurrence. Remove the bladder cuff with the ureter.'},
{id:'ut4',topic:'UTUC',level:'exam',section:'7. Perioperative systemic / local treatment',stem:'pT3N0 UTUC after nephroureterectomy, fit for chemotherapy. Recommendation based on the POUT trial?',options:['Adjuvant platinum-based chemotherapy','Observation only','Adjuvant radiotherapy alone','Adjuvant ADT'],answer:0,explain:'POUT showed that adjuvant platinum chemotherapy improves disease-free survival in pT2–T4 and/or N+ UTUC.'},
{id:'ut5',topic:'UTUC',level:'resident',section:'2. Histology / risk stratification',stem:'48-year-old with UTUC and a family history of colorectal cancer. Which hereditary condition should be screened for?',options:['Lynch syndrome','BRCA2 mutation','Von Hippel–Lindau disease','Birt–Hogg–Dubé syndrome'],answer:0,explain:'UTUC is a Lynch-associated tumour. Screen patients under 60 or with a personal or family history of Lynch-type cancers.'},
// ---------------- Ca Penis ----------------
{id:'pe1',topic:'Ca Penis',level:'resident',section:'4. cN0 groins — do not miss occult disease',stem:'pT2 penile SCC, groins clinically normal (cN0). Recommended groin management?',options:['Invasive nodal staging: DSNB or modified inguinal lymphadenectomy','Surveillance alone','Groin radiotherapy','Bilateral pelvic lymphadenectomy'],answer:0,explain:'For pT1b and above in cN0 groins, offer invasive staging (dynamic sentinel node biopsy or modified inguinal lymphadenectomy), because occult nodal disease is common.'},
{id:'pe2',topic:'Ca Penis',level:'intern',section:'3. Primary tumour treatment',stem:'Small superficial tumour confined to the glans. Preferred surgical approach?',options:['Penile-preserving surgery (wide local excision or glansectomy)','Total penectomy','Partial penectomy with a 2 cm margin','Radiotherapy only'],answer:0,explain:'Organ-sparing surgery with clear margins (a few millimetres can be enough) gives good oncological control and preserves function.'},
{id:'pe3',topic:'Ca Penis',level:'exam',section:'6. cN3 / bulky disease — exact logic',stem:'Fixed bulky inguinal nodes (cN3). Recommended initial approach?',options:['Neoadjuvant TIP chemotherapy, then surgery in responders','Immediate radical inguinal lymphadenectomy','Palliative care only','Groin radiotherapy alone'],answer:0,explain:'For cN3 disease, give neoadjuvant cisplatin-based chemotherapy (TIP), then consolidative lymphadenectomy if the nodes respond.'},
{id:'pe4',topic:'Ca Penis',level:'exam',section:'10. cN1–cN3 / contralateral / pelvic nodes',stem:'Inguinal lymphadenectomy shows 3 positive nodes with extranodal extension. Next step?',options:['Ipsilateral pelvic lymph node dissection','Observation','Contralateral groin radiotherapy only','Repeat inguinal dissection'],answer:0,explain:'Three or more positive inguinal nodes (pN2), or extranodal extension, carries a high risk of pelvic spread. Offer ipsilateral pelvic dissection.'},
{id:'pe5',topic:'Ca Penis',level:'resident',section:'3. Primary tumour treatment',stem:'Penile intraepithelial neoplasia (PeIN) on the glans. Reasonable first-line treatment?',options:['Topical imiquimod or 5-fluorouracil','Partial penectomy','Inguinal lymphadenectomy','Systemic chemotherapy'],answer:0,explain:'PeIN can be treated with topical therapy, laser, or glans resurfacing for persistent disease. It does not need radical surgery.'},
// ---------------- Ca Testis ----------------
{id:'te1',topic:'Ca Testis',level:'intern',section:'1. Diagnostic pathway',stem:'Firm intratesticular mass on ultrasound in a 27-year-old. Correct surgical approach?',options:['Inguinal orchidectomy','Trans-scrotal biopsy','Trans-scrotal orchidectomy','Fine-needle aspiration'],answer:0,explain:'Inguinal orchidectomy with high cord ligation. Avoid scrotal violation, because it changes lymphatic drainage. Draw AFP, β-hCG and LDH before surgery.'},
{id:'te2',topic:'Ca Testis',level:'resident',section:'5. Stage I seminoma',stem:'Stage I seminoma, 3 cm, no rete testis invasion, normal markers. Preferred management?',options:['Surveillance','Adjuvant radiotherapy 30 Gy','Three cycles of BEP','Retroperitoneal lymph node dissection'],answer:0,explain:'Low-risk stage I seminoma: surveillance is preferred. One cycle of carboplatin is an option for selected patients. Avoid routine radiotherapy.'},
{id:'te3',topic:'Ca Testis',level:'resident',section:'6. Stage I NSGCT',stem:'Stage I non-seminoma with lymphovascular invasion. Options that EAU supports?',options:['One cycle of adjuvant BEP or surveillance','Retroperitoneal radiotherapy','Four cycles of EP','Immediate chemotherapy for metastatic disease'],answer:0,explain:'LVI-positive stage I NSGCT has a relapse risk of about 50%. One cycle of BEP cuts it to about 2–3%. Surveillance is also acceptable after counselling.'},
{id:'te4',topic:'Ca Testis',level:'exam',section:'3. TNM / stage',stem:'Under TNM 9, which finding makes a testicular tumour at least pT2?',options:['Epididymal invasion','Tumour >3 cm in a seminoma','Invasion of the rete testis stroma alone','Elevated AFP'],answer:0,explain:'Epididymal invasion (or LVI, or hilar soft-tissue invasion) makes the tumour pT2. Size over 3 cm splits seminoma pT1 into pT1a and pT1b.'},
{id:'te5',topic:'Ca Testis',level:'resident',section:'4. IGCCCG metastatic risk',stem:'Metastatic NSGCT, IGCCCG good prognosis. Standard chemotherapy?',options:['Three cycles of BEP (or four of EP if bleomycin is contraindicated)','Four cycles of BEP','One cycle of carboplatin','High-dose chemotherapy with stem cell rescue'],answer:0,explain:'Good prognosis: 3× BEP. Intermediate or poor prognosis: 4× BEP (or VIP if bleomycin is unsuitable).'},
{id:'te6',topic:'Ca Testis',level:'exam',section:'8. Residual masses',stem:'4 cm residual retroperitoneal mass after chemotherapy for seminoma. Next step?',options:['FDG-PET at least 6 weeks after chemotherapy','Immediate RPLND','Radiotherapy to the mass','Surveillance CT only, regardless of size'],answer:0,explain:'For seminoma residuals over 3 cm, FDG-PET (at least 6 weeks after chemotherapy) helps tell viable tumour from fibrosis, which guides surgery.'},
// ---------------- Ca Kidney ----------------
{id:'rc1',topic:'Ca Kidney',level:'resident',section:'3. Bosniak 2019',stem:'Cystic renal lesion classified as Bosniak IIF. Management?',options:['Imaging surveillance','Partial nephrectomy','Radical nephrectomy','Percutaneous biopsy in all cases'],answer:0,explain:'Bosniak IIF is mostly benign. Follow it with imaging. Surgery or active surveillance is discussed for Bosniak III and IV.'},
{id:'rc2',topic:'Ca Kidney',level:'intern',section:'4. TNM & surgical treatment',stem:'Solid 3.2 cm enhancing renal mass (cT1a), healthy 55-year-old. Preferred treatment?',options:['Partial nephrectomy','Radical nephrectomy','Systemic therapy','Observation only'],answer:0,explain:'For T1a tumours (and T1b where feasible), partial nephrectomy preserves renal function with equivalent cancer control.'},
{id:'rc3',topic:'Ca Kidney',level:'resident',section:'6. Adjuvant therapy',stem:'Clear-cell RCC pT3a G3 N0 after nephrectomy. Adjuvant option based on KEYNOTE-564?',options:['Pembrolizumab for 1 year','Sunitinib for 5 years','Radiotherapy to the renal bed','Interferon-alpha'],answer:0,explain:'KEYNOTE-564 showed improved overall survival with 1 year of adjuvant pembrolizumab in intermediate-high or high-risk clear-cell RCC.'},
{id:'rc4',topic:'Ca Kidney',level:'exam',section:'7. IMDC & metastatic treatment',stem:'Which of these is NOT an IMDC risk factor?',options:['LDH more than 1.5 times the upper limit of normal','Karnofsky performance status below 80%','Less than 1 year from diagnosis to systemic therapy','Neutrophil count above the upper limit of normal'],answer:0,explain:'IMDC: KPS <80%, <1 year to treatment, Hb below normal, calcium, neutrophils or platelets above normal. LDH is a MSKCC criterion.'},
{id:'rc5',topic:'Ca Kidney',level:'resident',section:'7. IMDC & metastatic treatment',stem:'Metastatic clear-cell RCC, IMDC intermediate risk. First-line standard?',options:['Immune checkpoint inhibitor-based combination','Sunitinib monotherapy','Cytoreductive nephrectomy followed by observation','Everolimus'],answer:0,explain:'IO-based combinations (for example nivolumab–ipilimumab, pembrolizumab–axitinib or lenvatinib, nivolumab–cabozantinib) are first-line standard.'},
{id:'rc6',topic:'Ca Kidney',level:'resident',section:'5. Active surveillance / ablation',stem:'1.8 cm solid renal mass in a frail 82-year-old with cardiac comorbidity. Reasonable first option?',options:['Active surveillance','Radical nephrectomy','Open partial nephrectomy','Systemic therapy'],answer:0,explain:'Small renal masses in frail or comorbid patients: active surveillance (or thermal ablation) is appropriate, because competing mortality outweighs cancer risk.'},
// ---------------- Urethral Cancer ----------------
{id:'uc1',topic:'Urethral Cancer',level:'intern',section:'1. Histology',stem:'Most common histological type of primary urethral carcinoma overall?',options:['Urothelial carcinoma','Squamous cell carcinoma','Adenocarcinoma','Melanoma'],answer:0,explain:'Urothelial carcinoma is the most common primary urethral cancer, followed by squamous cell carcinoma.'},
{id:'uc2',topic:'Urethral Cancer',level:'resident',section:'3. Local / nodal treatment',stem:'Lymphatic drainage of the anterior (penile) male urethra?',options:['Inguinal nodes','Obturator nodes only','Para-aortic nodes','Presacral nodes'],answer:0,explain:'The anterior urethra drains to the inguinal nodes; the posterior urethra drains to the pelvic nodes.'},
{id:'uc3',topic:'Urethral Cancer',level:'resident',section:'3. Local / nodal treatment',stem:'Distal male urethral carcinoma, T2N0. Recommended surgical principle?',options:['Urethra-sparing surgery or partial urethrectomy with negative margins','Radical cystoprostatectomy in all cases','Radiotherapy alone','Observation'],answer:0,explain:'For distal tumours, partial urethrectomy or urethra-sparing surgery with negative frozen-section margins is acceptable.'},
{id:'uc4',topic:'Urethral Cancer',level:'exam',section:'4. Systemic treatment',stem:'Locally advanced (T3–4 or N+) urethral SCC. Preferred approach?',options:['Multimodal: chemoradiotherapy and/or cisplatin-based chemotherapy with surgery','Surgery alone','Observation','Intravesical BCG'],answer:0,explain:'Locally advanced urethral carcinoma needs multimodal treatment, discussed by an MDT. Chemoradiotherapy is a good option for SCC.'},
// ---------------- Adrenal ----------------
{id:'ad1',topic:'Adrenal / Neuroendocrine',level:'intern',section:'1. Incidentaloma evaluation',stem:'Incidental 2.5 cm homogeneous adrenal nodule, 6 HU on unenhanced CT. Further imaging?',options:['None needed: it is benign','Repeat CT at 6 and 12 months','MRI with chemical shift','Adrenal biopsy'],answer:0,explain:'ESE/ENSAT 2023: a homogeneous lesion of 10 HU or less is benign whatever its size, so no further imaging is needed.'},
{id:'ad2',topic:'Adrenal / Neuroendocrine',level:'resident',section:'1. Incidentaloma evaluation',stem:'Hormonal test recommended for every adrenal incidentaloma?',options:['1 mg overnight dexamethasone suppression test','24-hour urinary VMA','Serum ACTH only','Plasma renin alone'],answer:0,explain:'Do a 1 mg DST in all patients: cortisol ≤50 nmol/L excludes autonomous secretion. Check aldosterone/renin if the patient is hypertensive or hypokalaemic.'},
{id:'ad3',topic:'Adrenal / Neuroendocrine',level:'exam',section:'1. Incidentaloma evaluation',stem:'According to ESE 2023, plasma or urinary metanephrines can be omitted when…',options:['the lesion measures 10 HU or less on unenhanced CT','the patient is normotensive','the lesion is under 4 cm','the patient is over 65'],answer:0,explain:'Phaeochromocytoma is very unlikely at 10 HU or less. Normal blood pressure does not exclude it.'},
{id:'ad4',topic:'Adrenal / Neuroendocrine',level:'resident',section:'2. Adrenocortical carcinoma / pheochromocytoma',stem:'Pre-operative preparation for phaeochromocytoma?',options:['Alpha-blockade for 7–14 days, adding a beta-blocker only after alpha-blockade','Beta-blocker first, then an alpha-blocker','No preparation if normotensive','Steroid cover only'],answer:0,explain:'Start alpha-blockade first (for example doxazosin or phenoxybenzamine) with fluid and salt loading. Starting a beta-blocker first risks a hypertensive crisis.'},
{id:'ad5',topic:'Adrenal / Neuroendocrine',level:'exam',section:'3. Functional and malignant adrenal pathway',stem:'Suspected adrenocortical carcinoma (6 cm, heterogeneous, 40 HU). Which step is NOT recommended?',options:['Percutaneous biopsy of the mass','Complete hormonal work-up','Staging CT of chest, abdomen and pelvis','Surgery in a high-volume centre'],answer:0,explain:'Do not biopsy a suspected ACC: it risks seeding and rarely changes management. Exclude phaeochromocytoma, stage the patient, and refer to an expert centre.'}
];
